 static void emit(Path dir,String name,WeatherNativeEndpointOS4.Snapshot s,long observed){try{byte[]b=wire(s);Files.write(dir.resolve(name+".bin"),b);Files.writeString(dir.resolve(name+".hex"),HexFormat.of().formatHex(b)+"\n");Files.writeString(dir.resolve(name+".json"),"{\"available\":"+s.available()+",\"flags\":"+s.flags()+",\"epoch\":"+s.epoch()+",\"revision\":"+s.revision()+",\"deadline\":"+s.deadline()+",\"device_level\":"+s.deviceLevel()+",\"card_type\":"+s.cardType()+",\"blur\":"+s.blur()+",\"observed_boottime_ns\":"+observed+",\"bytes\":48,\"source\":\"production Java writer; host Parcel adapter, not Android capture\"}\n");}catch(Exception e){throw new AssertionError(e);}}
 static void corpus(Path dir){try{Files.createDirectories(dir);}catch(Exception e){throw new AssertionError(e);}reset();var e=endpoint();emit(dir,"cold_unavailable",read(e),now.get());set(e,"epoch",0x1122334455667788L);set(e,"revision",0x2233445566778800L);for(int n=0;n<=3;n++){publish(e,prefs("allow_hook",true,"weather_device_level",""+n,"weather_card_display_type","3","weather_unlock_blur",true));emit(dir,"active_raw_"+n,read(e),now.get());}publish(e,prefs("allow_hook",true));emit(dir,"active_defaults",read(e),now.get());var active=read(e);now.set(active.deadline());emit(dir,"delivered_expired",active,now.get());emit(dir,"expired_unavailable",read(e),now.get());publish(e,prefs("allow_hook",false,"weather_device_level","0"));emit(dir,"disabled",read(e),now.get());ContentResolver.failure="query";check(!e.refreshFromProvider());emit(dir,"failed_unavailable",read(e),now.get());clean();}
